effect.shader:
#define PI 3.14159265359
float h11(float p){
p = fract(p * 0.1031);
p *= p + 33.33;
p *= p + p;
return fract(p);
}
float h21(vec2 p){
vec3 p3 = fract(vec3(p.xyx) * 0.1031);
p3 += dot(p3, p3.yzx + 33.33);
return fract((p3.x + p3.y) * p3.z);
}
vec3 rgb2yiq(vec3 c){
float y = dot(c, vec3(0.299, 0.587, 0.114));
float i = dot(c, vec3(0.595716, -0.274453, -0.321263));
float q = dot(c, vec3(0.211456, -0.522591, 0.311135));
return vec3(y, i, q);
}
vec3 yiq2rgb(vec3 c){
float r = c.x + 0.9563 * c.y + 0.6210 * c.z;
float g = c.x - 0.2721 * c.y - 0.6474 * c.z;
float b = c.x - 1.1070 * c.y + 1.7046 * c.z;
return vec3(r, g, b);
}
vec3 sampleYIQ(vec2 uv){
return rgb2yiq(texture2DCv(inputImg.texture, clamp(uv, 0.001, 0.999)).rgb);
}
void main(){
vec2 res = acScreenSize;
vec2 uv  = acScreenNorm;
float line = floor(uv.y * res.y);
float seed = randomSeed * 0.137 + 1.0;
float t    = acTime;
float invW = 1.0 / res.x;
float invH = 1.0 / res.y;
float linesFromBottom = res.y - line;
float xshift = 0.0;
if(headEnabled){
float hsTop    = headOffset;
float hsBottom = headOffset + headHeight;
if(linesFromBottom > hsTop && linesFromBottom <= hsBottom){
float f  = (linesFromBottom - hsTop) / max(headHeight, 1.0);
float sh = (headHShift * invW) * (1.0 - f);
if(midLineEnabled){
float jit = (h21(vec2(line, seed)) - 0.5) * midLineJitter;
float pos = clamp(midLinePosition + jit, 0.0, 1.0);
if(uv.x > pos) xshift += sh;
} else {
xshift += sh;
}
}
}
float tnActive = 0.0;
if(linesFromBottom <= trackingHeight && trackingHeight > 0.5){
float f = 1.0 - linesFromBottom / max(trackingHeight, 1.0);
tnActive = f;
float wav = sin(uv.y * res.y * 0.6 + t * 9.0) * (trackingWaveIntensity * invW) * f;
wav += (h21(vec2(line, seed + 7.0)) - 0.5) * (trackingWaveIntensity * invW) * f;
xshift += wav;
}
vec2 suv  = vec2(uv.x + xshift, uv.y);
float xpix = (uv.x + xshift) * res.x;
float sub = subcarrier;
float phaseDeg = 0.0;
if(scanlinePhaseShift == 1) phaseDeg = 90.0;
else if(scanlinePhaseShift == 2) phaseDeg = 180.0;
else if(scanlinePhaseShift == 3) phaseDeg = 270.0;
float demErr = radians(phaseDeg) * mod(line + scanlinePhaseOffset, 4.0);
demErr += (h21(vec2(line, seed + 3.0)) - 0.5) * 0.7;
demErr += t * 0.6;
float sY = 0.0, sI = 0.0, sQ = 0.0, wsum = 0.0;
for(int k = -6; k <= 6; k++){
float fk = float(k);
vec3 s  = sampleYIQ(suv + vec2(fk * invW, 0.0));
float xp   = xpix + fk;
float encP = sub * xp;
float demP = sub * xp + demErr;
float comp = s.x + s.y * cos(encP) + s.z * sin(encP);
float w = exp(-fk * fk * 0.16);
sY += comp * w;
sI += comp * cos(demP) * w;
sQ += comp * sin(demP) * w;
wsum += w;
}
float Yo = sY / wsum;
float Io = 2.0 * sI / wsum * chromaGain;
float Qo = 2.0 * sQ / wsum * chromaGain;
vec3 yiq = vec3(Yo, Io, Qo);
if(chromaDemod == 0){
vec3 a = sampleYIQ(suv + vec2( invW, 0.0));
vec3 b = sampleYIQ(suv + vec2(-invW, 0.0));
yiq.y = (yiq.y + a.y * chromaGain + b.y * chromaGain) / 3.0;
yiq.z = (yiq.z + a.z * chromaGain + b.z * chromaGain) / 3.0;
} else if(chromaDemod == 2 || chromaDemod == 3){
vec3 up  = sampleYIQ(suv + vec2(0.0, invH));
vec3 up2 = (chromaDemod == 3) ? sampleYIQ(suv + vec2(0.0, 2.0 * invH)) : up;
yiq.y = mix(yiq.y, (up.y + up2.y) * 0.5 * chromaGain, 0.5);
yiq.z = mix(yiq.z, (up.z + up2.z) * 0.5 * chromaGain, 0.5);
}
float chromaPx = 0.0;
if(chromaLowpassIn == 1) chromaPx = 1.5;
else if(chromaLowpassIn == 2) chromaPx = 2.5;
if(lowpassType == 1) chromaPx *= 0.7;
else if(lowpassType == 2) chromaPx = 0.0;
if(chromaPx > 0.01){
float si = 0.0, sq = 0.0, sw = 0.0;
for(int k = -3; k <= 3; k++){
float fk = float(k);
float xp = xpix + fk * chromaPx;
vec3 s = sampleYIQ(suv + vec2(fk * chromaPx * invW, 0.0));
float encP = sub * xp;
float demP = sub * xp + demErr;
float comp = s.x + s.y * cos(encP) + s.z * sin(encP);
float w = exp(-fk * fk * 0.35);
si += comp * cos(demP) * w;
sq += comp * sin(demP) * w;
sw += w;
}
yiq.y = 2.0 * si / sw * chromaGain;
yiq.z = 2.0 * sq / sw * chromaGain;
}
if(inputLuma == 2){
float yl = 0.0, w = 0.0;
for(int k = -2; k <= 2; k++){
float fk = float(k);
yl += sampleYIQ(suv + vec2(fk * invW, 0.0)).x; w += 1.0;
}
yiq.x = yl / w;
} else if(inputLuma == 1){
float yb = 0.0, w = 0.0;
for(int k = -2; k <= 2; k++){
float fk = float(k);
yb += sampleYIQ(suv + vec2(fk * invW, 0.0)).x; w += 1.0;
}
yb /= w;
yiq.x += (yiq.x - yb) * 0.6;
}
if(noiseEnabled){
float nfreq = mix(2.0, 40.0, noiseFrequency);
float n = (h21(vec2(line * 0.5 + floor(t * 60.0), seed)) - 0.5);
int oct = int(noiseDetail + 0.5);
float amp = 0.5;
for(int o = 0; o < 5; o++){
if(o >= oct) break;
float fo = float(o) + 1.0;
n += (h21(vec2(uv.x * res.x * (nfreq * 0.02) * fo + line, seed + fo)) - 0.5) * amp;
amp *= 0.6;
}
yiq.x += n * noiseIntensity * 0.6;
}
if(lumaSmear > 0.001){
float sm = lumaSmear * 10.0 * invW;
float yl = sampleYIQ(suv - vec2(sm, 0.0)).x;
yiq.x = mix(yiq.x, max(yiq.x, yl * 0.95), lumaSmear);
}
if(abs(compositeSharpen) > 0.001){
float yb = 0.0, w = 0.0;
for(int k = -2; k <= 2; k++){
float fk = float(k);
yb += sampleYIQ(suv + vec2(fk * invW, 0.0)).x; w += 1.0;
}
yb /= w;
yiq.x += (yiq.x - yb) * compositeSharpen;
}
if(useField != 3){
float parity = mod(line + floor(t * 50.0), 2.0);
if(useField == 1) parity = mod(line + 1.0 + floor(t * 50.0), 2.0);
if(useField != 2){
yiq.x *= (1.0 - 0.10 * parity);
}
}
if(snow > 0.001){
float ax = floor(uv.x * res.x / mix(1.0, 6.0, snowAnisotropy));
float sp = h21(vec2(ax + floor(t * 120.0) * 1.3, line * 1.7 + seed));
float thresh = 1.0 - clamp(snow * 0.01, 0.0, 1.0);
if(sp > thresh){
yiq = vec3(0.9, 0.0, 0.0);
}
}
if(tnActive > 0.001){
float st = h21(vec2(uv.x * res.x + floor(t * 120.0) * 1.9, line + seed + 11.0));
yiq.x = mix(yiq.x, st, trackingSnow * tnActive);
yiq.x += (st - 0.5) * trackingNoise * tnActive;
}
vec3 outc = clamp(yiq2rgb(yiq), 0.0, 1.0);
vec3 orig = texture2DCv(inputImg.texture, clamp(uv, 0.001, 0.999)).rgb;
gl_FragColor = vec4(mix(orig, outc, intensity), 1.0);
}
